def _derive_verified_binding(selected: VerifiedPack, part_number: str) -> DeviceBinding:
    """Derive an exact part binding from digest-verified bytes."""

    normalize_part_number(part_number)
    try:
        DeviceSupportResolver._validate_archive(selected)
        pack = CmsisPack(io.BytesIO(selected.payload))
        matches = tuple(
            device
            for device in pack.devices
            if _pdsc_leaf_matches_part(device.part_number, part_number)
        )
    except PackProvisionError:
        raise
    except Exception as exc:
        raise PackProvisionError(
            f"candidate CMSIS-Pack metadata could not be parsed: {exc}"
        ) from exc
    if len(matches) != 1:
        raise PackProvisionError(
            "candidate CMSIS-Pack must expose exactly one PDSC leaf matching the exact MCU part"
        )
    try:
        from pyocd.target import normalise_target_type_name  # type: ignore[import-untyped]

        device = matches[0]
        leaf = device.part_number
        target = normalise_target_type_name(leaf)
    except Exception as exc:
        raise PackProvisionError(
            f"candidate PDSC leaf has no canonical pyOCD target: {exc}"
        ) from exc
    return DeviceBinding(part_number, leaf, target, _compatible_core_identity(device))


def _pdsc_ancestry_terms(selected: VerifiedPack, pdsc_device: str) -> tuple[str, ...]:
    """Read family/subfamily terms from the exact leaf's verified PDSC ancestry."""

    try:
        with zipfile.ZipFile(io.BytesIO(selected.payload)) as archive:
            root = ET.fromstring(archive.read(_select_pdsc_member(archive.infolist())))
    except (ET.ParseError, OSError, zipfile.BadZipFile) as exc:
        raise PackProvisionError("verified PDSC ancestry could not be parsed") from exc
    for family in root.iter():
        if family.tag.rsplit("}", 1)[-1] != "family":
            continue
        for subfamily in family:
            if subfamily.tag.rsplit("}", 1)[-1] != "subFamily":
                continue
            if any(
                child.tag.rsplit("}", 1)[-1] == "device"
                and child.attrib.get("Dname", "").casefold() == pdsc_device.casefold()
                for child in subfamily.iter()
            ):
                return tuple(
                    value.strip()
                    for value in (
                        family.attrib.get("Dfamily", ""),
                        subfamily.attrib.get("DsubFamily", ""),
                    )
                    if value.strip()
                )
    raise PackProvisionError("exact verified PDSC leaf has no family/subfamily ancestry")


def derive_candidate_binding(pack_path: Path, part_number: str) -> DeviceBinding:
    """Derive one exact/wildcard PDSC leaf and canonical target from quarantined bytes."""

    payload = read_pack_bytes(pack_path)
    return _derive_verified_binding(
        VerifiedPack(
            pack_path,
            PackSpec("candidate", "", pack_path.name, "", "0" * 64),
            payload,
        ),
        part_number,
    )


@dataclass(frozen=True, slots=True)
class DeviceSupportCandidate:
    """One verified exact part-to-pack-to-target candidate issued by the server."""

    candidate_id: str
    part_number: str
    pdsc_device: str
    pyocd_target: str
    pack_id: str
    pack_filename: str
    pack_sha256: str
    pdsc_ancestry_terms: tuple[str, ...]
    identity_proof: LiveIdentityProof | None = None

    @classmethod
    def from_verified_pack(
        cls, selected: VerifiedPack, binding: DeviceBinding
    ) -> "DeviceSupportCandidate":
        material = "\0".join(
            (
                selected.spec.sha256,
                binding.part_number.casefold(),
                binding.pdsc_device.casefold(),
                binding.pyocd_target.casefold(),
                *(
                    term.casefold()
                    for term in _pdsc_ancestry_terms(selected, binding.pdsc_device)
                ),
                str(binding.identity_proof.to_document() if binding.identity_proof else None),
            )
        ).encode("utf-8")
        return cls(
            hashlib.sha256(material).hexdigest(),
            binding.part_number,
            binding.pdsc_device,
            binding.pyocd_target,
            selected.spec.id,
            selected.spec.filename,
            selected.spec.sha256,
            _pdsc_ancestry_terms(selected, binding.pdsc_device),
            binding.identity_proof,
        )

    @property
    def support_id(self) -> str:
        """Return the immutable identifier persisted by generic profiles.

        Candidate IDs are already domain-separated from their component tuple
        and are deterministic for the exact registered authority.  Naming the
        persisted value separately avoids callers mistaking a target string for
        authority.
        """

        return self.candidate_id

    @property
    def legacy_support_id(self) -> str:
        """Reproduce the pre-ancestry identifier for offline legacy-profile replay."""

        material = "\0".join(
            (
                self.pack_sha256,
                self.part_number.casefold(),
                self.pdsc_device.casefold(),
                self.pyocd_target.casefold(),
                str(self.identity_proof.to_document() if self.identity_proof else None),
            )
        ).encode("utf-8")
        return hashlib.sha256(material).hexdigest()

    def to_authority_document(self) -> dict[str, str]:
        """Return the closed server-generated source record for a profile/map."""

        return {
            "kind": "resolved_pack",
            "support_id": self.support_id,
    def legacy_support_id(self) -> str:
        """Reproduce the pre-ancestry identifier for offline legacy-profile replay."""

        material = "\0".join(
            (
                self.pack_sha256,
                self.part_number.casefold(),
                self.pdsc_device.casefold(),
                self.pyocd_target.casefold(),
                str(self.identity_proof.to_document() if self.identity_proof else None),
            )
        ).encode("utf-8")
        return hashlib.sha256(material).hexdigest()

    def to_authority_document(self) -> dict[str, str]:
        """Return the closed server-generated source record for a profile/map."""

        return {
            "kind": "resolved_pack",
            "support_id": self.support_id,
            "pack_id": self.pack_id,
            "pack_filename": self.pack_filename,
            "pack_sha256": self.pack_sha256,
            "pdsc_device": self.pdsc_device,
            "pyocd_target": self.pyocd_target,
        }

    def datasheet_identity_terms(self) -> tuple[str, ...]:
        """Return only exact PDSC authority terms eligible for PDF applicability."""

        return (self.part_number, self.pdsc_device, *self.pdsc_ancestry_terms)

    def matches_authority_document(self, source: Mapping[str, str]) -> bool:
        """Accept a legacy ID only when every immutable pack field still replays exactly."""

        expected = self.to_authority_document()
        return (
            all(source.get(key) == value for key, value in expected.items() if key != "support_id")
            and source.get("support_id") in {self.support_id, self.legacy_support_id}
            and set(source) == set(expected)
        )


